-- =====================================================================
-- StockFlow - datos de muestra (inventario industrial)
-- Generado el 2026-10-17. MySQL 8.0.19 o superior (Aiven).
--
-- Que inserta:
--   9 categorias, 4 almacenes, 8 proveedores, 46 productos,
--   ~653 movimientos de entrada/salida (ultimos 4 meses) y el stock por
--   almacen calculado a partir de esos movimientos.
--   10 productos quedan por debajo del stock minimo (2 en cero) para
--   que aparezcan en Alertas.
--
-- No crea ni modifica usuarios: los movimientos se asignan al usuario
-- 'almacenero' (o al primer Admin si no existe) y algunas salidas al Admin.
--
-- Se puede ejecutar mas de una vez: lo que ya existe (por nombre, codigo,
-- RUC o SKU) no se duplica, y los movimientos solo se cargan para los
-- productos que aun no tienen ninguno.
--
-- En DBeaver: abrir este archivo con la conexion de Aiven, base stockflow,
-- y ejecutar como script (Alt+X).
-- =====================================================================

START TRANSACTION;

SET @u_admin := (SELECT MIN(Id) FROM Users WHERE Role = 'Admin' AND IsActive = 1);
SET @u_alm   := COALESCE((SELECT Id FROM Users WHERE Username = 'almacenero' AND IsActive = 1), @u_admin);

