) AS v
JOIN Products p ON p.Sku = v.Sku
JOIN Warehouses wh ON wh.Code = v.Wh
WHERE NOT EXISTS (SELECT 1 FROM StockMovements m WHERE m.ProductId = p.Id);

-- ---------- Stock por almacen (recalculado desde los movimientos) ----------
INSERT INTO WarehouseStocks (ProductId, WarehouseId, Quantity)
SELECT t.ProductId, t.WarehouseId, t.Qty
FROM (
  SELECT m.ProductId, m.WarehouseId,
         SUM(CASE WHEN m.Type = 'In' THEN m.Quantity ELSE -m.Quantity END) AS Qty
  FROM StockMovements m
  JOIN Products p ON p.Id = m.ProductId
  WHERE p.Sku IN ('HER-001', 'HER-002', 'HER-003', 'HER-004', 'HER-005', 'HER-006', 'EPP-001', 'EPP-002', 'EPP-003', 'EPP-004', 'EPP-005', 'EPP-006', 'EPP-007', 'EPP-008', 'REP-001', 'REP-002', 'REP-003', 'REP-004', 'REP-005', 'REP-006', 'LUB-001', 'LUB-002', 'LUB-003', 'LUB-004', 'ELE-001', 'ELE-002', 'ELE-003', 'ELE-004', 'ELE-005', 'ELE-006', 'TOR-001', 'TOR-002', 'TOR-003', 'TOR-004', 'NEU-001', 'NEU-002', 'NEU-003', 'NEU-004', 'SOL-001', 'SOL-002', 'SOL-003', 'SOL-004', 'LIM-001', 'LIM-002', 'LIM-003', 'LIM-004')
  GROUP BY m.ProductId, m.WarehouseId
) AS t
ON DUPLICATE KEY UPDATE Quantity = t.Qty;

COMMIT;

-- ---------- Comprobacion ----------
SELECT 'Categorias' AS Tabla, COUNT(*) AS Filas FROM Categories
UNION ALL SELECT 'Almacenes', COUNT(*) FROM Warehouses
UNION ALL SELECT 'Proveedores', COUNT(*) FROM Suppliers
UNION ALL SELECT 'Productos', COUNT(*) FROM Products
UNION ALL SELECT 'Movimientos', COUNT(*) FROM StockMovements
UNION ALL SELECT 'Stock por almacen', COUNT(*) FROM WarehouseStocks;

-- Productos activos bajo el stock minimo (lo mismo que muestra Alertas)
SELECT p.Sku, p.Name, p.MinStock, COALESCE(SUM(ws.Quantity), 0) AS StockTotal
FROM Products p
LEFT JOIN WarehouseStocks ws ON ws.ProductId = p.Id
WHERE p.IsActive = 1
GROUP BY p.Id, p.Sku, p.Name, p.MinStock
HAVING StockTotal < p.MinStock
ORDER BY p.Sku;
